def parse_amount(raw: str) -> float:
    # POS exports amounts like "1,234.50" -> strip thousands separators
    return float(raw.replace(",", ""))

def parse_row(row):
    return {
        "store": row["store_id"],
        "amount": parse_amount(row["amount"]),
        "bills": int(row["bills"]),
    }
